--- qoder.cmd ---
@echo off
setlocal EnableExtensions

where powershell.exe >nul 2>&1
if errorlevel 1 (
  echo Qoder dispatcher requires powershell.exe but it was not found in PATH. 1>&2
  echo Try installing PowerShell, or run "qodercli" / "qoder.exe" directly. 1>&2
  exit /b 127
)

set "DISPATCHER=%~dp0qoder-dispatcher.ps1"
powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%DISPATCHER%" -- %*
exit /b %ERRORLEVEL%

--- dispatcher head ---
$ErrorActionPreference = 'Stop'

function Find-Cli {
  if ($env:QODER_CLI_BIN -and (Test-Path -PathType Leaf $env:QODER_CLI_BIN)) {
    return $env:QODER_CLI_BIN
  }
  # Resolve via PATHEXT so npm-installed `.cmd` shims and curl-bash `.exe` both win.
  # Get-Command can emit every PATH match (for example the standalone CLI plus
  # an IDE-bundled qodercli.exe). Keep normal PATH priority but return one
  # scalar path; passing the whole array to PowerShell's call operator joins
  # the paths into a single, invalid command name.
  $cmd = Get-Command qodercli -CommandType Application -ErrorAction SilentlyContinue |
    Select-Object -First 1
  if ($cmd) { return $cmd.Source }
  $userBin = Join-Path $env:USERPROFILE '.qoder\bin\qodercli\qodercli.exe'
  if (Test-Path -PathType Leaf $userBin) { return $userBin }
  return $null
}

function Test-IsNpmShim([string]$path) {
  try {
    $head = Get-Content -LiteralPath $path -TotalCount 30 -ErrorAction SilentlyContinue
    if ($head) {
      $joined = $head -join "`n"
      if ($joined -match 'qoder-npm-dispatcher') { return $true }
    }
  } catch {}
  return $false
}

function Test-IsCliDispatcherWrapper([string]$path) {
  try {
    $head = Get-Content -LiteralPath $path -TotalCount 30 -ErrorAction SilentlyContinue
    if ($head) {
      $joined = $head -join "`n"
      if ($joined -match 'qoder-dispatcher\.ps1') { return $true }
    }
  } catch {}
  return $false
}

