        });
        console.log('HTTP', r.status);
        console.log((await r.text()).slice(0, 600));
      } catch (e) { console.log('请求失败:', e.message); }
    }
  } else {
    console.log('\n（未设 QODER_TRY_CLAIM=1 或无 CLAIMABLE 活动，跳过 claim 写操作）');
