MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQDA8iMH5c02LilrsERw9t6Pv5Nc
4k6Pz1EaDicBMpdpxKduSZu5OANqUq8er4GM95omAGIOPOh+Nx0spthYA2BqGz+l
6HRkPJ7S236FZ73In/KVuLnwI8JJ2CbuJap8kvheCCZpmAWpb/cPx/3Vr/J6I17
XcW+ML9FoCI6AOvOzwIDAQAB
-----END PUBLIC KEY-----`;

function parseRsaPub(pem) {
  const body = pem.split('\n').filter((l) => !l.includes('BEGIN') && !l.includes('END')).join('');
  const der = Buffer.from(body, 'base64');
  const readTlv = (buf, i) => {
    const tag = buf[i];
    let len = buf[i + 1], j = i + 2;
    if (len & 0x80) { const nb = len & 0x7f; len = Number(buf.slice(j, j + nb).readBigBE ? buf.slice(j, j + nb).reduce((a, b) => (a << 8n) | BigInt(b), 0n) : 0); j += nb; }
    return { tag, value: buf.slice(j, j + len), next: j + len };
  };
  const seq = readTlv(der, 0);
  const alg = readTlv(seq.value, 0);
  const bits = readTlv(seq.value, alg.next);
  const bitsBody = bits.value.slice(1);          // 去 unused-bits 字节
  const rsaseq = readTlv(bitsBody, 0);
  const nTlv = readTlv(rsaseq.value, 0);
  const eTlv = readTlv(rsaseq.value, nTlv.next);
  const toBig = (b) => b.reduce((a, x) => (a << 8n) | BigInt(x), 0n);
  return { n: toBig(nTlv.value), e: toBig(eTlv.value) };
}
const { n: RSA_N, e: RSA_E } = parseRsaPub(SERVER_PUB_PEM);
console.log('RSA modulus bits:', RSA_N.toString(2).length, '| e:', RSA_E.toString());

