  if (der[i] === 0x02 && (der[i + 1] === 0x81 || der[i + 1] === 0x82)) {
    const nlen = der[i + 1] === 0x81 ? der[i + 2] : der.readUInt16BE(i + 2);
    if (nlen >= 120 && nlen <= 140) { nStart = i; break; }
  }
}
console.log('modulus TLV idx:', nStart);
if (nStart >= 0) {
  const hdrLen = der[nStart + 1] === 0x81 ? 3 : 4;
  const nlen = der[nStart + 1] === 0x81 ? der[nStart + 2] : der.readUInt16BE(nStart + 2);
  const n = der.slice(nStart + hdrLen, nStart + hdrLen + nlen);
  console.log('modulus bytes:', nlen, '| bits:', toBig(n).toString(2).length);
