  + 'XcW+ML9FoCI6AOvOzwIDAQAB\n'
  + '-----END PUBLIC KEY-----';
const body = PEM.split('\n').filter((l) => !l.includes('BEGIN') && !l.includes('END')).join('');
const der = Buffer.from(body, 'base64');
const hex = der.toString('hex');
const toBig = (b) => b.reduce((a, x) => (a << 8n) | BigInt(x), 0n);

console.log('der len:', der.length);
console.log('hex:', hex.slice(0, 60), '...');

// [0] 30 81 9f  -> SEQUENCE, len=0x9f=159
console.log('\n[0] tag=0x' + der[0].toString(16), 'lenbyte=0x' + der[1].toString(16), '=> seqlen', der[1] & 0x7f);
// seq.value 从 index 3 开始
const seqStart = 3;
// AlgorithmIdentifier: 30 0d 06 09 2a 86 48 86 f7 0d 01 01 01 05 00
console.log('[alg] tag=0x' + der[seqStart].toString(16), 'len=', der[seqStart + 1]);
const algEnd = seqStart + 2 + der[seqStart + 1];
console.log('[alg] ends at', algEnd, 'next bytes:', der.slice(algEnd, algEnd + 8).toString('hex'));
// BIT STRING: 03 81 8d 00 30 81 89 ...
const bs = algEnd;
console.log('[bits] tag=0x' + der[bs].toString(16), 'lenbyte=0x' + der[bs + 1].toString(16), '=> len', der[bs + 1] & 0x7f);
const bitsBody = der.slice(bs + 3 + 1);   // tag + lenbyte + unused-bits(0x00)
console.log('[bits] body head:', bitsBody.slice(0, 8).toString('hex'));
// RSAPublicKey SEQUENCE: 30 81 89 02 81 81 00 c0 f2 ...
console.log('[rsa] tag=0x' + bitsBody[0].toString(16), 'lenbyte=0x' + bitsBody[1].toString(16), '=> len', bitsBody[1] & 0x7f);
const rsaBody = bitsBody.slice(3);
console.log('[rsa] body head:', rsaBody.slice(0, 10).toString('hex'));
// modulus INTEGER: 02 81 81 00 c0 f2 23 ...
console.log('[n] tag=0x' + rsaBody[0].toString(16), 'lenbyte=0x' + rsaBody[1].toString(16), '=> len', rsaBody[1] & 0x7f);
const nStart = 3;
const n = rsaBody.slice(nStart, nStart + (rsaBody[1] & 0x7f));
console.log('[n] bytes:', n.length, 'bits:', toBig(n).toString(2).length, 'head:', n.slice(0, 6).toString('hex'));
// exponent INTEGER: 02 03 01 00 01
const eOff = nStart + (rsaBody[1] & 0x7f);
console.log('[e] at offset', eOff, 'bytes:', rsaBody.slice(eOff, eOff + 5).toString('hex'));
console.log('[e] tag=0x' + rsaBody[eOff].toString(hex0 = 16), 'len=', rsaBody[eOff + 1]);
const e = rsaBody.slice(eOff + 2, eOff + 2 + rsaBody[eOff + 1]);
console.log('[e] value bytes:', e.toString('hex'), '=> e =', toBig(e));
