  + '6HRkPJ7S236FZ73In/KVuLnwI8JJ2CbuJap8kvheCCZpmAWpb/cPx/3Vr/J6I17\n'
  + 'XcW+ML9FoCI6AOvOzwIDAQAB\n'
  + '-----END PUBLIC KEY-----';
const crypto = require('crypto');

// 1) 原生导入
try {
  const k = crypto.createPublicKey(PEM);
  console.log('createPublicKey OK:', k.asymmetricKeyType, k.asymmetricKeyDetails);
} catch (e) { console.log('createPublicKey FAIL:', e.message); }

// 2) 原生公钥加密
try {
  const k = crypto.createPublicKey(PEM);
  const ct = crypto.publicEncrypt({ key: k, padding: crypto.constants.RSA_PKCS1_PADDING }, Buffer.from('0123456789abcdef', 'utf8'));
  console.log('publicEncrypt OK, ct len:', ct.length, 'b64 head:', ct.toString('base64').slice(0, 24));
} catch (e) { console.log('publicEncrypt FAIL:', e.message); }

// 3) 正确的手写 TLV 解析
const toBig = (b) => b.reduce((a, x) => (a << 8n) | BigInt(x), 0n);
const body = PEM.split('\n').filter((l) => !l.includes('BEGIN') && !l.includes('END')).join('');
const der = Buffer.from(body, 'base64');
function readTlv(buf, i) {
  const tag = buf[i];
  let len = buf[i + 1], j = i + 2;
  if (len & 0x80) {
    const nb = len & 0x7f;
    len = Number(toBig(buf.slice(j, j + nb)));
    j += nb;
  }
  return { tag, value: buf.slice(j, j + len), next: j + len };
}
const seq = readTlv(der, 0);
const alg = readTlv(seq.value, 0);
const bits = readTlv(seq.value, alg.next);
const bitsBody = bits.value.slice(1);
const rsaseq = readTlv(bitsBody, 0);
const nTlv = readTlv(rsaseq.value, 0);
const eTlv = readTlv(rsaseq.value, nTlv.next);
console.log('\n手写解析: n bits =', toBig(nTlv.value).toString(2).length, '| e =', toBig(eTlv.value));
console.log('n bytes =', nTlv.value.length, '| e bytes =', eTlv.value.length);
