const toBig = (b) => b.reduce((a, x) => (a << 8n) | BigInt(x), 0n);
const body = PEM.split('\n').filter((l) => !l.includes('BEGIN') && !l.includes('END')).join('');
const der = Buffer.from(body, 'base64');

// 正确的 DER TLV 解析：
//   header = tag(1) + length
//   length: 0x00..0x7f → 短形式，值本身；0x81 → 后 1 字节为长度；0x82 → 后 2 字节为长度
function readTlv(buf, i) {
  const tag = buf[i];
  const b1 = buf[i + 1];
  let len, j;
  if (b1 < 0x80) { len = b1; j = i + 2; }          // 短形式
  else {
    const nb = b1 & 0x7f;                            // 长字节数
    len = Number(toBig(buf.slice(i + 2, i + 2 + nb)));
    j = i + 2 + nb;
  }
  return { tag, value: buf.slice(j, j + len), next: j + len };
}
const seq = readTlv(der, 0);
const alg = readTlv(seq.value, 0);
const bits = readTlv(seq.value, alg.next);
const bitsBody = bits.value.slice(1);               // BIT STRING 去掉 unused-bits 字节
const rsaseq = readTlv(bitsBody, 0);
const nTlv = readTlv(rsaseq.value, 0);
const eTlv = readTlv(rsaseq.value, nTlv.next);
console.log('\n修正解析: n bits =', toBig(nTlv.value).toString(2).length,
  '| e =', toBig(eTlv.value), '| n bytes =', nTlv.value.length, '| e bytes =', eTlv.value.length);

// 用原生 crypto 做 RSA 运算（PEM 导入失败，改用 jwk 或直接构造）
const k = {
  key: {
    kty: 'RSA',
    n: Buffer.from(toBig(nTlv.value).toString(16).padStart(256, '0'), 'hex').toString('base64url'),
    e: 'AQAB',
  },
  format: 'jwk',
};
console.log('JWK n:', k.key.n.slice(0, 20) + '…', '| e:', k.key.e);
try {
  const pub = crypto.createPublicKey(k);
  const ct = crypto.publicEncrypt({ key: pub, padding: crypto.constants.RSA_PKCS1_PADDING }, Buffer.from('0123456789abcdef', 'utf8'));
  console.log('原生 publicEncrypt OK, ct len:', ct.length);
} catch (e) { console.log('原生 publicEncrypt FAIL:', e.message); }

