{"content":"const PEM = '-----BEGIN PUBLIC KEY-----\n'
  + 'MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQDA8iMH5c02LilrsERw9t6Pv5Nc\n'
  + '4k6Pz1EaDicBMpdpxKduSZu5OANqUq8er4GM95omAGIOPOh+Nx0spthYA2BqGz+l\n'
  + '6HRkPJ7S236FZ73In/KVuLnwI8JJ2CbuJap8kvheCCZpmAWpb/cPx/3Vr/J6I17\n'
  + 'XcW+ML9FoCI6AOvOzwIDAQAB\n'
  + '-----END PUBLIC KEY-----';
const body = PEM.split('\n').filter((l) => !l.includes('BEGIN') && !l.includes('END')).join('');
const der = Buffer.from(body, 'base64');
console.log('der len:', der.length);
console.log('hex:', der.toString('hex'));

// 逐字节标注
const toBig = (b) => b.reduce((a, x) => (a << 8n) | BigInt(x), 0n);

// [0] 0x30 SEQUENCE
// [1] 0x81 长形式，长度 1 字节：[2]=0x9f → 159
console.log('\nidx0 tag=0x' + der[0].toString(16), 'lenForm=0x' + der[1].toString(16));
const seqBodyStart = 3;  // 0x30 + 0x81 + 0x9f
console.log('seqBody starts at', seqBodyStart);

// alg: [3] 0x30 [4] 0x0d(13) → alg 占 13 字节，结尾 = 3+2+13 = 18
console.log('alg tag=0x' + der[seqBodyStart].toString(16), 'len=', der[seqBodyStart + 1]);
const bitsStart = seqBodyStart + 2 + der[seqBodyStart + 1];
console.log('bits(BIT STRING) starts at', bitsStart, 'tag=0x' + der[bitsStart].toString(16), 'lenForm=0x' + der[bitsStart + 1].toString(16));
// BIT STRING: tag(1) + lenForm(1) + len(1 if 0x81) 或值 + unused(1)
let bitsHeaderLen, bitsLen;
if (der[bitsStart + 1] & 0x80) { bitsHeaderLen = 3; bitsLen = der[bitsStart + 2]; }
else { bitsHeaderLen = 2; bitsLen = der[bitsStart + 1]; }
console.log('bits headerLen=', bitsHeaderLen, 'len=', bitsLen);
const bitsBodyStart = bitsStart + bitsHeaderLen + 1;   // +1 跳过 unused-bits 字节
console.log('bitsBody starts at', bitsBodyStart, 'first byte=0x' + der[bitsBodyStart].toString(16));

// RSAPublicKey SEQUENCE: bitsBody[0]=0x30 bitsBody[1]=0x81 bitsBody[2]=0x89 → 137
console.log('rsa tag=0x' + der[bitsBodyStart].toString(16), 'lenForm=0x' + der[bitsBodyStart + 1].toString(16));
const rsaBodyStart = bitsBodyStart + 3;  // 0x30 + 0x81 + 0x89
console.log('rsaBody starts at', rsaBodyStart);

// modulus INTEGER: rsaBody[0]=0x02 rsaBody[1]=0x81 rsaBody[2]=0x81 → 129
console.log('n tag=0x' + der[rsaBodyStart].toString(16), 'lenForm=0x' + der[rsaBodyStart + 1].toString(16));
let nHeaderLen, nLen;
if (der[rsaBodyStart + 1] & 0x80) { nHeaderLen = 3; nLen = der[rsaBodyStart + 2]; }
else { nHeaderLen = 2; nLen = der[rsaBodyStart + 1]; }
const nValueStart = rsaBodyStart + nHeaderLen;
console.log('n headerLen=', nHeaderLen, 'len=', nLen, 'valueStart=', nValueStart, 'firstByte=0x' + der[nValueStart].toString(16));

// exponent INTEGER 紧接 modulus
const eStart = nValueStart + nLen;
console.log('e tag=0x' + der[eStart].toString(16), 'len=', der[eStart + 1], 'value:', der.slice(eStart + 2, eStart + 2 + der[eStart + 1]).toString('hex'));
const eValue = der.slice(eStart + 2, eStart + 2 + der[eStart + 1]);
console.log('e =', toBig(eValue));

const nBuf = der.slice(nValueStart, nValueStart + nLen);
console.log('n bits =', toBig(nBuf).toString(2).length);
// JWK 需要无符号大端，去掉前导 0x00
const nTrim = nBuf[0] === 0 ? nBuf.slice(1) : nBuf;
console.log('n(jwk) =', Buffer.from(nTrim).toString('base64url').slice(0, 24) + '…');
","file_path":"C:\opt\workstations\project\web\RelayGate\logs\debug-rsa-trace2.js"}

