{"content":"// 用从 qoder_sign.py 精确抽取的公钥，验证 DER 解析 + 原生 RSA 加密
const fs = require('fs');
const crypto = require('crypto');
const PEM = fs.readFileSync('C:/opt/workstations/project/web/RelayGate/logs/qoder-pub-correct.pem', 'utf8');
const toBig = (b) => b.reduce((a, x) => (a << 8n) | BigInt(x), 0n);

// 1) 原生导入（Node 对 PEM 要求严格）
try {
  const k = crypto.createPublicKey(PEM);
  console.log('原生 createPublicKey OK:', k.asymmetricKeyType, '| bits:', k.asymmetricKeyDetails && k.asymmetricKeyDetails.modulusLength);
} catch (e) { console.log('原生 createPublicKey FAIL:', e.message); }

// 2) DER 解析（正确版）
const body = PEM.split('\n').filter((l) => !l.includes('BEGIN') && !l.includes('END')).join('');
const der = Buffer.from(body, 'base64');
console.log('der len:', der.length, '| head:', der.slice(0, 12).toString('hex'));

function readTlv(buf, i) {
  const tag = buf[i], b1 = buf[i + 1];
  let len, j;
  if (b1 < 0x80) { len = b1; j = i + 2; }
  else { const nb = b1 & 0x7f; len = Number(toBig(buf.slice(i + 2, i + 2 + nb))); j = i + 2 + nb; }
  return { tag, value: buf.slice(j, j + len), next: j + len };
}
const seq = readTlv(der, 0);
const alg = readTlv(seq.value, 0);
const bits = readTlv(seq.value, alg.next);
const rsaseq = readTlv(bits.value.slice(1), 0);       // 去 unused-bits
const nTlv = readTlv(rsaseq.value, 0);
const eTlv = readTlv(rsaseq.value, nTlv.next);
console.log('n bits =', toBig(nTlv.value).toString(2).length, '| e =', toBig(eTlv.value),
  '| n bytes =', nTlv.value.length, '| e bytes =', eTlv.value.length);

// 3) 用 JWK 走原生公钥加密（验证 modulus/exponent 解析正确）
const nTrim = nTlv.value[0] === 0 ? nTlv.value.slice(1) : nTlv.value;
try {
  const pub = crypto.createPublicKey({ key: { kty: 'RSA', n: Buffer.from(nTrim).toString('base64url'), e: 'AQAB' }, format: 'jwk' });
  const ct = crypto.publicEncrypt({ key: pub, padding: crypto.constants.RSA_PKCS1_PADDING }, Buffer.from('0123456789abcdef', 'utf8'));
  console.log('原生 publicEncrypt OK, ct len:', ct.length, '| b64 head:', ct.toString('base64').slice(0, 24));
} catch (e) { console.log('原生 publicEncrypt FAIL:', e.message); }
","file_path":"C:\opt\workstations\project\web\RelayGate\logs\debug-rsa-final.js"}

