{"content":"// 与 qoder_sign.py 的测试向量对照，定位签名差异
const crypto = require('crypto');
const PEM = '-----BEGIN PUBLIC KEY-----\n'
  + 'MIGfMA0GCSqGSIb3DQEBAQUAA4GNADCBiQKBgQDA8iMH5c02LilrsERw9t6Pv5Nc\n'
  + '4k6Pz1EaDicBMpdpxKduSZu5OANqUq8er4GM95omAGIOPOh+Nx0spthYA2BqGz+l\n'
  + '6HRkPJ7S236FZz73In/KVuLnwI8JJ2CbuJap8kvheCCZpmAWpb/cPx/3Vr/J6I17\n'
  + 'XcW+ML9FoCI6AOvOzwIDAQAB\n'
  + '-----END PUBLIC KEY-----';
const CUSTOM = '_doRTgHZBKcGVjlvpC,@aFSx#DPuNJme&i*MzLOEn)sUrthbf%Y^w.(kIQyXqWA!';
const STD = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const S2C = {}; for (let i = 0; i < 64; i++) S2C[STD[i]] = CUSTOM[i];
function qoderEncode(buf) {
  const std = Buffer.from(buf).toString('base64');
  const n = std.length, a = Math.floor(n / 3);
  const rearranged = std.slice(n - a) + std.slice(a, n - a) + std.slice(0, a);
  return [...rearranged].map((ch) => (ch === '=' ? '$' : S2C[ch])).join('');
}

console.log('=== qoderEncode 对照 ===');
console.log('JS :', qoderEncode(Buffer.from('{"x":1}')));
console.log('PY : ep$$BMn%mYKI  (来自 qoder2api-hub 注释/测试)');
console.log('match:', qoderEncode(Buffer.from('{"x":1}')) === 'ep$$BMn%mYKI');

console.log('\n=== json_sorted_compact 对照 ===');
// Python: json.dumps("key", ensure_ascii=False) + ":" + json.dumps(value, ensure_ascii=False)
const sortedCompact = (obj) => {
  const parts = [];
  for (const k of Object.keys(obj).sort()) {
    const kJson = JSON.stringify(k);                       // json.dumps(str(k))
    const v = obj[k];
    const vJson = v === null ? '""' : JSON.stringify(v);   // Python: None -> ""
    parts.push(`${kJson}:${vJson}`);
  }
  return '{' + parts.join(',') + '}';
};
const payloadObj = { cosyVersion: '1.1.64', ideVersion: '', info: 'INFO', requestId: 'RID', version: 'v1' };
console.log('JS :', sortedCompact(payloadObj));
const expectPy = '{"cosyVersion":"1.1.64","ideVersion":"","info":"INFO","requestId":"RID","version":"v1"}';
console.log('expect:', expectPy);
console.log('match:', sortedCompact(payloadObj) === expectPy);

console.log('\n=== 签名公式核对 ===');
// 参考: sig = md5(payload_b64 + "\n" + cosy_key + date + "\n" + body + "\n" + path)
const payloadB64 = Buffer.from(sortedCompact(payloadObj)).toString('base64');
const cosyKey = 'COSYKEY';
const date = '1791882000';
const body = 'BODYENC';
const path = '/api/v2/service/pro/sse/agent_chat_generation';
const raw = [payloadB64, cosyKey, date, body, path].join('\n');
console.log('raw =', JSON.stringify(raw));
console.log('sig =', crypto.createHash('md5').update(raw, 'utf8').digest('hex'));

// Python 等价
console.log('\n(用 python 复算，应一致)');
","file_path":"C:\opt\workstations\project\web\RelayGate\logs\debug-sign-vector.js"}

