    + `already=${summary.already} failed=${summary.failed} emptyList=${summary.emptyList}`);

  // 任务日志（面板「任务日志」可见）
  appendTaskLog({
    task: 'qoder-rewards',
    trigger,
    ok: summary.claimed,
    failed: summary.failed,
    total: summary.total,
    already: summary.already,
    skipped: summary.skipped,
    emptyList: summary.emptyList,
    claim: doClaim,
    startedAt,
    finishedAt: state.lastRunAt,
    detail: summary.claimedDetails,
  });

