{"content":"'use strict';
const C = require('C:/opt/workstations/project/web/RelayGate/src/qoder/catalog');
const inputs = ['{}', '{"x":1}', 'abc', 'a', 'ab', 'abcd', 'hello world'];
for (const s of inputs) {
  const b = Buffer.from(s);
  const std = b.toString('base64');
  const out = C.qoderEncode(b);
  console.log(JSON.stringify(s).padEnd(12), 'std=' + std.padEnd(16), 'enc=' + out);
}

// 官方算法复算（独立实现，用于交叉验证）
function refEncode(buf) {
  const ALPHA = '_doRTgHZBKcGVjlvpC,@aFSx#DPuNJme&i*MzLOEn)sUrthbf%Y^w.(kIQyXqWA!';
  const STD = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const map = {};
  for (let i = 0; i < 64; i++) map[STD[i]] = ALPHA[i];
  const std = buf.toString('base64');
  const n = std.length;
  const a = Math.floor(n / 3);
  const arr = std.slice(n - a) + std.slice(a, n - a) + std.slice(0, a);
  let out = '';
  for (const ch of arr) out += ch === '=' ? '$' : map[ch];
  return out;
}
console.log('\n交叉验证（我的实现 vs 独立参考实现）:');
let allOk = true;
for (const s of [...inputs, 'x'.repeat(100), JSON.stringify({ a: 1, b: [1, 2, 3] })]) {
  const b = Buffer.from(s);
  const mine = C.qoderEncode(b);
  const ref = refEncode(b);
  const ok = mine === ref;
  if (!ok) allOk = false;
  console.log((ok ? '  OK  ' : '  DIFF'), JSON.stringify(s).slice(0, 20).padEnd(22), mine === ref ? '' : `${mine} vs ${ref}`);
}
console.log(allOk ? '\n全部一致' : '\n存在差异！');
","file_path":"C:\opt\workstations\project\web\RelayGate\logs\tmp-encode-check.js"}

