      console.log('\n=== 清理 ===');
      for (const a of store.list().filter((x) => variant.isEdition(x.edition, variant.QODER))) store.remove(a.id);
      console.log('  qoder 账号已清空');
    } catch (e) {
      console.error('路由验证失败:', e);
    } finally {
      server.close();
    }
  });
})().catch((e) => { console.error(e); process.exitCode = 1; });
