      signal: AbortSignal.timeout(90000),
    });
    console.log('HTTP', r.status, 'ct=', r.headers.get('content-type'));
    const txt = await r.text();
    console.log('RAW (first 1500):\n' + txt.slice(0, 1500));
  }
})();
