/* 临时探针 3：usage 末帧 / tool_calls / 429 形态 */
process.env.WORKSPACE_DIR = 'C:/opt/workstations/project/web/RelayGate/output';
const store = require('C:/opt/workstations/project/web/RelayGate/src/credentials/store');
const variant = require('C:/opt/workstations/project/web/RelayGate/src/platform/variant');

const intl = store.list().find((a) => variant.isEdition(a.edition, variant.QODER) && variant.qoderRealmOfAccount(a) === 'intl');
const full = store.get(intl.id);
const url = variant.qoderGatewayBase('intl') + variant.variantOf(variant.QODER).paths.chat;
const H = { Authorization: `Bearer ${full.token}`, 'Content-Type': 'application/json' };

async function post(body) {
  const r = await fetch(url, { method: 'POST', headers: H, body: JSON.stringify(body), signal: AbortSignal.timeout(90000) });
  const t = await r.text();
  return { status: r.status, text: t, ct: r.headers.get('content-type') };
}

(async () => {
  console.log('--- stream tail (usage?) ---');
  const s = await post({ model: 'qmodel', messages: [{ role: 'user', content: 'hi' }], stream: true });
  console.log('HTTP', s.status);
  const lines = s.text.trim().split('\n').map((l) => l.trim()).filter(Boolean);
  console.log('frame count:', lines.length);
  console.log('LAST 3 FRAMES:');
  for (const l of lines.slice(-3)) console.log('  ' + l.slice(0, 400));
  const hasUsage = lines.some((l) => l.includes('"usage":{"') || /"usage":\s*\{[^n]/.test(l));
  console.log('has non-null usage:', hasUsage);

  console.log('\n--- tool_calls ---');
  const tools = [{
    type: 'function',
    function: {
      name: 'get_weather',
      description: 'Get weather for a city',
      parameters: { type: 'object', properties: { city: { type: 'string' } }, required: ['city'] },
    },
  }];
  const tc = await post({ model: 'qmodel', messages: [{ role: 'user', content: 'What is the weather in Beijing? Use the tool.' }], tools, stream: false, max_tokens: 300 });
  console.log('HTTP', tc.status);
  console.log(tc.text.slice(0, 900));

  console.log('\n--- non-stream usage present? ---');
  const ns = await post({ model: 'qmodel', messages: [{ role: 'user', content: 'hi' }], stream: false });
  console.log('HTTP', ns.status);
  try { console.log('usage =', JSON.stringify(JSON.parse(ns.text).usage)); } catch { console.log(ns.text.slice(0, 300)); }

  console.log('\n--- 429 provider_error raw (efficient) ---');
  const rl = await post({ model: 'efficient', messages: [{ role: 'user', content: 'hi' }], stream: false });
  console.log('HTTP', rl.status, 'ct=', rl.ct);
  console.log(rl.text.slice(0, 600));
})();
