  if (!acct) return '账号不存在';
  const realm = variant.qoderRealmOfAccount(acct);
  if (!variant.qoderChatRealms().includes(realm)) {
    return realm === 'cn'
      ? 'Qoder 国内版对话面未开放（/model/v1/* 实测 503，需 COSY 老协议）'
      : `Qoder ${realm} 区域对话面未开放`;
