 * 探测单个模型是否真能调用（供运维面板与目录校准用）。
 * @returns {Promise<{ok:boolean, status:number, code:string|null, message:string}>}
 */
async function probeModel(acct, model) {
  const r = await chatOnce(acct, {
    model,
    messages: [{ role: 'user', content: 'hi' }],
    stream: false,
