{"content":"'use strict';
/* 临时：端到端验证 /v1/qoder/chat/completions（真上游 + 真本机账号） */
process.env.WORKSPACE_DIR = 'C:/opt/workstations/project/web/RelayGate/output';
process.env.ADMIN_KEY = 'test-admin-key';
process.env.LOG_LEVEL = 'debug';

const http = require('node:http');
const app = require('C:/opt/workstations/project/web/RelayGate/src/index');
const apiKeys = require('C:/opt/workstations/project/web/RelayGate/src/credentials/api-keys');
const variant = require('C:/opt/workstations/project/web/RelayGate/src/platform/variant');
const store = require('C:/opt/workstations/project/web/RelayGate/src/credentials/store');

const srv = http.createServer(app);

function req(method, path, { body, key, raw } = {}) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const r = http.request({
      host: '127.0.0.1', port: srv.address().port, path, method,
      headers: {
        ...(data ? { 'Content-Type': 'application/json' } : {}),
        ...(key ? { Authorization: `Bearer ${key}` } : {}),
      },
    }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        resolve({ status: res.statusCode, text, ct: res.headers.get('content-type') });
      });
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}

(async () => {
  await new Promise((r) => srv.listen(0, '127.0.0.1', r));
  const port = srv.address().port;
  console.log('listening on', port);

  // 创建三把转发密钥：通用 / trae / workbuddy（验证平台隔离）
  const kAll = apiKeys.createKey({ label: 't-all', kind: 'access', platform: 'all' });
  const kTrae = apiKeys.createKey({ label: 't-trae', kind: 'access', platform: 'trae' });
  const kWb = apiKeys.createKey({ label: 't-wb', kind: 'access', platform: 'workbuddy' });
  console.log('keys:', kAll.id, kTrae.id, kWb.id);

  // 账号实况
  const qoder = store.list().filter((a) => variant.isEdition(a.edition, variant.QODER));
  console.log('qoder accounts:', qoder.map((a) => ({ id: a.id, realm: a.qoderRealm, enabled: a.enabled })));

  console.log('\n=== 1. 未鉴权 ===');
  const r1 = await req('POST', '/v1/qoder/chat/completions', { body: { model: 'qmodel', messages: [{ role: 'user', content: 'hi' }] } });
  console.log(r1.status, r1.text.slice(0, 160));

  console.log('\n=== 2. 非流式（通用密钥，qmodel）===');
  const r2 = await req('POST', '/v1/qoder/chat/completions', {
    body: { model: 'qmodel', messages: [{ role: 'user', content: 'reply with the single word: pong' }], stream: false },
    key: kAll.plainKey || kAll.plain,
  });
  console.log(r2.status, r2.ct);
  console.log(r2.text.slice(0, 700));

  console.log('\n=== 3. 不可调用模型（qfmodel，应 400 且不发上游）===');
  const r3 = await req('POST', '/v1/qoder/chat/completions', {
    body: { model: 'qfmodel', messages: [{ role: 'user', content: 'hi' }], stream: false },
    key: kAll.plainKey || kAll.plain,
  });
  console.log(r3.status, r3.text.slice(0, 300));

  console.log('\n=== 4. 平台密钥越界（trae key 应 403）===');
  const r4 = await req('POST', '/v1/qoder/chat/completions', {
    body: { model: 'qmodel', messages: [{ role: 'user', content: 'hi' }], stream: false },
    key: kTrae.plainKey || kTrae.plain,
  });
  console.log(r4.status, r4.text.slice(0, 250));

  console.log('\n=== 5. 流式（SSE 原样透传）===');
  const r5 = await req('POST', '/v1/qoder/chat/completions', {
    body: { model: 'qmodel', messages: [{ role: 'user', content: 'count 1 2 3' }], stream: true },
    key: kAll.plainKey || kAll.plain,
  });
  console.log(r5.status, r5.ct);
  console.log('frames:', r5.text.split('\n').filter((l) => l.startsWith('data:')).length);
  console.log('has [DONE]:', r5.text.includes('[DONE]'));
  console.log('tail:', r5.text.slice(-400));

  console.log('\n=== 6. /v1/qoder/status 的 chat 段 ===');
  const r6 = await req('GET', '/v1/qoder/status', { key: 'test-admin-key' });
  console.log(r6.status);
  const j = JSON.parse(r6.text);
  console.log(JSON.stringify(j.platform.chat, null, 2));

  console.log('\n=== 7. Trae 池未被 qoder 污染（只跑本地断言，不打上游）===');
  const pool = require('C:/opt/workstations/project/web/RelayGate/src/credentials/pool');
  const snap = pool.snapshot();
  console.log('pool accounts:', snap.accounts.map((a) => ({ label: a.label.slice(0, 24), usable: a.usable })));

  srv.close();
  process.exit(0);
})().catch((e) => { console.error('FAILED', e); process.exit(1); });
","file_path":"C:\Users\bing\AppData\Local\Temp\qoder-probe\e2e.js"}

